/// Call the midi-event-close entrypoint on one registered bridge.
uint32_t call_midi_event_close(
    JNIEnv *env,
    uint64_t session_handle,
    uint64_t session_id
) {
    jobject bridge = resolve_bridge(env, session_handle);
    if (bridge == nullptr) {
        return HOST_STATUS_NOT_FOUND;
    }


    jint status = env->CallIntMethod(
        bridge,
        eventClose_method,
        static_cast<jlong>(session_id)
    );
    env->DeleteLocalRef(bridge);

    if (env->ExceptionCheck()) {
        env->ExceptionClear();
        return HOST_STATUS_FAILED;
    }

    return static_cast<uint32_t>(status);
}

/// Call the midi-output-write entrypoint on one registered bridge.
uint32_t call_midi_output_write(
    JNIEnv *env,
    uint64_t session_handle,
    uint64_t session_id,
    AndroidHostMidiOutputRecordHeaderSlice headers,
    uint32_t record_count,
    NativeU8Slice blob_bytes,
    uint32_t *records_written
) {
    jobject bridge = resolve_bridge(env, session_handle);
    if (bridge == nullptr) {
        return HOST_STATUS_NOT_FOUND;
    }

    jobjectArray headers_value = encode_AndroidHostMidiOutputRecordHeaderSlice(env, headers);
    if (headers_value == nullptr) {
        if (env->ExceptionCheck()) {
            env->ExceptionClear();
        }
        env->DeleteLocalRef(bridge);
        return HOST_STATUS_FAILED;
    }
    jintArray blob_bytes_value = encode_u8_slice(env, blob_bytes);
    if (blob_bytes_value == nullptr) {
        if (headers_value != nullptr) { env->DeleteLocalRef(headers_value); }
        if (env->ExceptionCheck()) {
            env->ExceptionClear();
        }
        env->DeleteLocalRef(bridge);
        return HOST_STATUS_FAILED;
    }

    jobject response_object = env->CallObjectMethod(
        bridge,
        outputWrite_method,
        static_cast<jlong>(session_id),
        headers_value,
        static_cast<jint>(record_count),
        blob_bytes_value
    );
    if (response_object == nullptr) {
        if (headers_value != nullptr) { env->DeleteLocalRef(headers_value); }
        if (blob_bytes_value != nullptr) { env->DeleteLocalRef(blob_bytes_value); }
        if (env->ExceptionCheck()) {
            env->ExceptionClear();
        }
        env->DeleteLocalRef(bridge);
        return HOST_STATUS_FAILED;
    }

    jint status = call_int_getter(env, response_object, "getStatus");
    if (status == HOST_STATUS_OK) {
        *records_written = static_cast<uint32_t>(call_int_getter(env, response_object, "getRecordsWritten"));
    }
    if (headers_value != nullptr) { env->DeleteLocalRef(headers_value); }
    if (blob_bytes_value != nullptr) { env->DeleteLocalRef(blob_bytes_value); }
    env->DeleteLocalRef(response_object);
    env->DeleteLocalRef(bridge);

    if (env->ExceptionCheck()) {
        env->ExceptionClear();
        return HOST_STATUS_FAILED;
    }

    return static_cast<uint32_t>(status);
}
